package com.inridemart.order;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class OrderService { final OrderRepositoryAdapter orders; final CatalogClient catalog; OrderService(OrderRepositoryAdapter o,CatalogClient c){orders=o;catalog=c;} @Transactional public Order create(UUID userId,String key,List<Line> lines){return orders.find(userId,key).orElseGet(()->{if(lines==null||lines.isEmpty())throw new IllegalArgumentException("Order must contain at least one item"); List<OrderItem> items=lines.stream().map(l->{var p=catalog.get(l.productId());return new OrderItem(p.id(),p.name(),l.quantity(),p.price(),p.currency());}).toList();return orders.save(Order.place(userId,key,items,Instant.now()));});} @Transactional(readOnly=true) public List<Order> mine(UUID userId){return orders.mine(userId);} @Transactional(readOnly=true) public Order mine(UUID userId,UUID id){var o=orders.byId(id).orElseThrow(()->new NoSuchElementException("Order not found"));if(!o.userId().equals(userId))throw new SecurityException("You can only access your own orders");return o;} @Transactional public Order updateStatus(UUID userId,UUID id,OrderStatus status){return orders.save(mine(userId,id).withStatus(status));} public record Line(UUID productId,int quantity){} }
